import React, { useEffect, useState } from "react";
import Header from "../../Layout/Header";
import Sidebar from "../../Layout/Sidebar";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import Swal from "sweetalert2";
import { individualLoginActivity } from "../../Redux/crmSlices/loginActivitySlice/LoginActivitySlice";
import TopCards from "../../Components/TopCards";

const LoginActivityList = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [loginActivities, setLoginActivities] = useState([]);
  const [searchQuery, setSearchQuery] = useState(""); // State to hold search query
  const [currentPage, setCurrentPage] = useState(1); // Current page state
  const [itemsPerPage, setItemsPerPage] = useState(10); // Items per page state

  const { data, count, loading,  status, error } = useSelector((state) => {

    // return false;
    console.log(state);
    return {
      data: state.rootReducer.LoginActivitySlice?.data,
      loading: state.rootReducer.LoginActivitySlice?.loading,
      count: state.rootReducer.LoginActivitySlice?.count,
      status: state.rootReducer.LoginActivitySlice?.status,
      error: state.rootReducer.LoginActivitySlice?.error,
    };
  });



  // Fetch leads whenever current page, items per page or searchQuery changes
  useEffect(() => {
    // const offset = (currentPage - 1) * itemsPerPage; // Calculate the offset based on the current page

    // if (searchQuery) {
    // //   dispatch(searchLead({ search: searchQuery, offset, limit: itemsPerPage })); // Dispatch search action
    // } else {
    // //   dispatch(fetchLead({ offset, limit: itemsPerPage })); // Dispatch fetch action if no search term
    // }

    dispatch(individualLoginActivity())

  }, [dispatch]);
  
  console.log("Result => " , data)

  useEffect(() => {
    if (data && data?.status) {
      
      setLoginActivities(data?.loginActivities);  // Update leads with the API response
    }
  }, [data]);  // Make sure to update leads whenever the response changes
  
  console.log(loginActivities);


  // Pagination logic
  const totalPages = Math.ceil(count / itemsPerPage);

  // Handle search input change
  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
    setCurrentPage(1); // Reset to page 1 when the search query changes
  };

  return (
    <div>
      <Header />
      <Sidebar />
      <div className="main-content">
        <div className="page-content">
          <div className="container-fluid">
            <TopCards/>
            <div className="row" style={{ fontFamily: "poppins" }}>
              <div className="col-lg-12">
                <div className="card">
                  <div className="card-header"></div>
                  <div className="card-body">
                    <div className="listjs-table" id="customerList">
                      <div className="row g-4 mb-3">
                        <div className="col-sm-auto">
                          
                          {/* Search */}
                          <div
                            className="col-10 d-flex "
                            style={{ marginTop: "20px" }}
                          >
                            <div className="search-box mx-2">
                              <input
                                type="text"
                                className="form-control w-auto"
                                id="searchMemberList"
                                placeholder="Name"
                                value={searchQuery}
                                onChange={handleSearchChange}
                              />
                              <i className="ri-search-line search-icon"></i>
                            </div>
                          </div>
                          {/* Search */}
                        </div>
                      </div>

                      <div className="table-responsive table-card mt-3 mb-1">
                        <table
                          className="table align-middle table-nowrap"
                          id="dataTableExample1"
                        >
                          <thead className="table-light">
                            <tr>
                              <th>User Name</th>
                              <th>Activity Role</th>
                              <th>IP Address</th>
                              <th>Agent</th>
                              <th>Add Information</th>
                              <th>Lat, Long</th>
                              <th>Login Time</th>
                            </tr>
                          </thead>
                          <tbody className="list form-check-all">
  {loading ? (
    <tr>
      <td colSpan={8} className="text-center">
        <span>Loading...</span>
      </td>
    </tr>
  ) : data && data.length > 0 ? (
    data.map((lead, key) => (
      <tr key={key}>
        <td>{lead.l_name}</td>
        <td>{lead.l_source}</td>
        <td>{lead.l_mobile}</td>
        <td>{lead.l_email}</td>
        <td>{lead.l_address}</td>
        <td>
          <div className="d-flex gap-2">
            {/* <button
              type="button"
              className="btn btn-sm btn-info"
              onClick={() => handleEdit(lead)}
            >
              <i className="fa fa-pencil-o"></i> Update
            </button>
            <button
              type="button"
              className="btn btn-sm btn-danger"
              onClick={() => handleDelete(lead)}
            >
              <i className="fa fa-trash-o"></i> Remove
            </button> */}
          </div>
        </td>
      </tr>
    ))
  ) : loginActivities && loginActivities.length > 0 ? (
    loginActivities.map((log, key) => (
      <tr key={key}>
        <td>{log.la_emp_name}</td>
        <td>{log.la_type}</td>
        <td>
          <div>
            {log.la_ip_address}
          </div>
          <div>
            <a href={"https://iplocation.io/ip/106.219.84.33"} target="_blank" className="text-decoration-underline" rel="noreferrer" >
              Check IP Details
            </a>
          </div>
        </td>
        <td>{log.la_agent}</td>
        <td>{log.la_add_information}</td>
        <td>
          <div>  
            {log.la_lat_long}
          </div>
          <div>
            <a href={"https://www.google.com/maps/place/" + log.la_lat_long} target="_blank" className="text-decoration-underline" rel="noreferrer" >
              Check Position
            </a>
          </div>
        </td>
        <td>{log.la_created_at}</td>
        <td>
        </td>
      </tr>
    ))
  ) : (
    <tr>
      <td colSpan={8} className="text-center">
        No leads available
      </td>
    </tr>
  )}
</tbody>

                        </table>

                        {/* Pagination */}
                        <div className="container mt-5">
                          <div className="d-flex justify-content-end align-items-center">
                            <nav aria-label="Page navigation">
                              <ul className="pagination pagination-lg">
                                <li className="page-item">
                                  <button
                                    className="page-link"
                                    onClick={() => setCurrentPage(currentPage - 1)}
                                    aria-disabled="true"
                                    disabled={currentPage === 1}
                                  >
                                    <span aria-hidden="true">&laquo;</span> Previous
                                  </button>
                                </li>

                                <li className="page-item disabled">
                                  <span className="page-link">
                                    Page {currentPage} of {totalPages}
                                  </span>
                                </li>

                                <li className="page-item">
                                  <button
                                    className="page-link"
                                    onClick={() => setCurrentPage(currentPage + 1)}
                                    aria-disabled="false"
                                    disabled={currentPage === totalPages}
                                  >
                                    Next <span aria-hidden="true">&raquo;</span>
                                  </button>
                                </li>
                              </ul>
                            </nav>
                          </div>
                        </div>
                        {/* Pagination */}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginActivityList;
