import React, { useEffect, useState } from "react";
import Header from "../../Layout/Header";
import Sidebar from "../../Layout/Sidebar";
import Footer from "../../Layout/Header";
import { useDispatch, useSelector } from "react-redux";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom";
import {
  addInquiry,
  deleteInquiry,
  fetchInquiry,
} from "../../Redux/crmSlices/Inquiry/InquirySlice";
import { Navigate } from "react-router-dom";
import TopCards from "../../Components/TopCards";

const Inquirylist = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [inquiry, setInquiry] = useState([]);
  const { data, count, loading, response } = useSelector((state) => {
    return {
      data: state.rootReducer.InquirySlice?.data?.data,
      loading: state.rootReducer.InquirySlice?.loading,
      response: state.rootReducer.InquirySlice?.response,
    };
  });
  useEffect(() => {
    dispatch(fetchInquiry());
  }, [dispatch]);
  useEffect(() => {
    if (response && response.data) {
      setInquiry(response.data);
    }
  }, [response]);
  const handleDelete = (inq) => {
    Swal.fire({
      title: "Are you sure?",
      text: `You won't be able to revert this!`,
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#d33",
      cancelButtonColor: "#3085d6",
      confirmButtonText: "Yes, delete it!",
    }).then((result) => {
      if (result.isConfirmed) {
        // Dispatch the delete inquiry action
        dispatch(deleteInquiry(inq.inq_id))
          .then(() => {
            // If deletion is successful, fetch the updated inquiry list
            dispatch(fetchInquiry());

            // Show success message after successful deletion
            Swal.fire(
              "Deleted!",
              `${inq.inq_name} has been deleted.`,
              "success"
            );
          })
          .catch((error) => {
            // Handle any errors that occur during the deletion
            Swal.fire(
              "Error!",
              "There was an issue deleting the inquiry.",
              "error"
            );
          });
      }
    });
  };

  const addQuotation = (data) => {
    console.log("=>",data.inq_id)
    localStorage.setItem("productId", data.inq_id);
    navigate("/create-quotation");
  };

  return (
    <div>
      <Header />
      <Sidebar />
      <div className="main-content">
        <div className="page-content">
          <div className="container-fluid">
               <TopCards/>
            <div className="row" style={{ fontFamily: "poppins" }}>
              <div className="col-lg-12">
                <div className="card">
                  <div className="card-header"></div>
                  <div className="card-body">
                    <div className="listjs-table" id="customerList">
                      <div className="row g-4 mb-3">
                        <div className="col-sm-auto">
                          <div>
                            <button
                              type="submit"
                              className="btn btn-success add-btn"
                              id="create-btn"
                              onClick={() => navigate("/add-inquiry")}
                            >
                              <i className="ri-add-line align-bottom me-1" />{" "}
                              Add
                            </button>
                          </div>
                        </div>
                      </div>
                      <div className="table-responsive table-card mt-3 mb-1">
                        <table
                          className="table align-middle table-nowrap"
                          id="dataTableExample1"
                        >
                          <thead className="table-light">
                            <tr>
                              <th class1Name="sort" data-sort="inq_name">
                               SR NO
                              </th>
                              <th class1Name="sort" data-sort="inq_name">
                                INQUIRY NO
                              </th>
                              <th className="sort" data-sort="inq_contact">
                                COMPANY
                              </th>
                              <th className="sort" data-sort="inq_email">
                                	CUSTOMER NAME
                              </th>
                              <th className="sort" data-sort="inq_status">
                                DRG NO
                              </th>
                              <th className="sort" data-sort="inq_status">
                                PRODUCT NAME
                              </th>
                              <th className="sort" data-sort="inq_status">
                                QTY
                              </th>
                              <th className="sort" data-sort="inq_status">
                                AMOUNT
                              </th>
                              <th className="sort" data-sort="inq_status">
                                TOTAL AMOUNT
                              </th>
                              <th className="sort" data-sort="inq_status">
                                GST / SEZ
                              </th>
                              <th className="sort" data-sort="inq_status">
                                Create Date
                              </th>
                              <th className="sort" data-sort="inq_status">
                                TOTAL AMOUNT
                              </th>
                              <th className="sort" data-sort="action">
                                Action
                              </th>
                            </tr>
                          </thead>
                          <tbody>
                           <td>1</td>
                            <td>252220	</td>
                            <td>LUPIN LTD 	</td>
                            <td>RAHUL SHARMA 		</td>
                            <td>AEG422	</td>
                            <td>AEG2232	</td>
                            <td>SS CHAIR</td>
                            <td>5</td>
                            <td>10000</td>
                            <td>5000</td>
                            <td>GST</td>
                            <td>5900</td>
                                     <td>
                                <ul className="list-inline hstack gap-2 mb-0">
                                  <li className="list-inline-item">
                                    <div className="dropdown">
                                      <button
                                        className="btn btn-soft-secondary btn-sm dropdown"
                                        type="button"
                                        data-bs-toggle="dropdown"
                                        aria-expanded="false"
                                      >
                                        <i className="ri-more-fill align-middle" />
                                      </button>
                                      <ul className="dropdown-menu dropdown-menu-end">
                                        <li>
                                          <a
                                            className="dropdown-item view-item-btn"
                                            href="javascript:void(0);"
                                          >
                                            <i className="ri-eye-fill align-bottom me-2 text-muted" />
                                            View
                                          </a>
                                        </li>
                                        <li>
                                          <a
                                            className="dropdown-item edit-item-btn"
                                            href="#showModal"
                                            data-bs-toggle="modal"
                                          >
                                            <i className="ri-pencil-fill align-bottom me-2 text-muted" />{" "}
                                            Edit
                                          </a>
                                        </li>
                                        <li>
                                          <a
                                            className="dropdown-item remove-item-btn"
                                            data-bs-toggle="modal"
                                            href="#deleteRecordModal"
                                          >
                                            <i className="ri-delete-bin-fill align-bottom me-2 text-muted" />{" "}
                                            Delete
                                          </a>
                                        </li>
                                      </ul>
                                    </div>
                                  </li>
                                </ul>
                              </td>
                          </tbody>

                          {/* <tbody className="list form-check-all">
                            {loading ? (
                              <tr>
                                <td colSpan={6} className="text-center">
                                  Loading...
                                </td>
                              </tr>
                            ) : inquiry?.length > 0 ? (
                              inquiry?.map((inq, key) => (
                                <tr key={key}>
                                  <td>{inq?.inq_name}</td>
                                  <td>{inq?.inq_contact}</td>
                                  <td>{inq?.inq_email}</td>
                                  <td>{inq?.inq_message}</td>
                                  <td> {inq?.inq_status} </td>
                                  <td> {inq?.p_name} </td>
                                  <td> {inq?.p_size} </td>
                                  <td> {inq?.p_moc} </td>
                                  <td> {inq?.p_thickness} </td>
                                  <td> {inq?.p_drg} </td>

                                  <td> {inq?.p_code} </td>
                                  <td> {inq?.p_info} </td>

                                  <td>
                                    <div className="d-flex gap-2">
                                      <div className="remove">
                                        <button
                                          type="button"
                                          className="btn btn-sm btn-danger remove-item-btn"
                                          onClick={() => handleDelete(inq)}
                                        >
                                          Remove
                                        </button>
                                      </div>
                                      <div className="remove">
                                        <button
                                          type="button"
                                          className="btn btn-sm btn-info remove-item-btn"
                                          onClick={() => addQuotation(inq)}
                                        >
                                          Quotation
                                        </button>
                                      </div>
                                    </div>
                                  </td>
                                  <td></td>
                                </tr>
                              ))
                            ) : (
                              <tr>
                                <td colSpan={6} className="text-center">
                                  No data found
                                </td>
                              </tr>
                            )}
                          </tbody> */}
                        </table>

                        <div className="noresult" style={{ display: "none" }}>
                          <div className="text-center">
                            <lord-icon
                              src="https://cdn.lordicon.com/msoeawqm.json"
                              trigger="loop"
                              colors="primary:#121331,secondary:#08a88a"
                              style={{ width: 75, height: 75 }}
                            />
                            <h5 className="mt-2">Sorry! No Result Found</h5>
                            <p className="text-muted mb-0">
                              We've searched more than 150+ Orders. We did not
                              find any orders for your search.
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Inquirylist;
